## Gio and Sam
# added an haproxy to better balance the requests
# between the webnodes
# http://www.openlibrary.org/admin?stats
#
#
# old conf (requests balanced by nginx)
#upstream webnodes {
#    server ol-web1.us.archive.org:8080;
#    server ol-web2.us.archive.org:8080;
#}
#
# using haproxy
upstream webnodes {
    server web_haproxy:7072;
}

map $http_user_agent $is_sus_user_agent {
    default 0;
    "~ByteSpider" 1;
    # Check for ancient browser user agents
    "~Firefox/([1-7]\.)" 1;
    "~Chrome/([1-9]|10)\." 1;
}

# Log likely bots caught in /authors random loop.
map $request_uri$args $is_sus_random_sort {
    default 0;
    "~^/authors/.*sort=random_" 1;
}

# Check empty referer
map $http_referer $is_empty_referer {
    default 0;
    "" 1;
}

map $request_uri$args $requires_referer {
    default 0;
    "~*^/(qrcode|admin|wp-login|show-records)" 1;
    "~*/edit" 1;
    "~*(v|m|action|redirect)=" 1;
}

map $is_empty_referer$requires_referer $is_sus_referer {
    default 0;
    "11" 1;
}

# Keep in sync with covers_nginx.conf
server {
    listen 80 default;
    listen [::]:443 ssl http2 ipv6only=on;
    listen 443 ssl http2;
    server_name localhost;

    ssl_certificate /etc/letsencrypt/live/openlibrary.org/fullchain.pem;
    ssl_certificate_key /etc/letsencrypt/live/openlibrary.org/privkey.pem;

    # Diffie-Hellman parameter for DHE ciphersuites, recommended 2048 bits
    ssl_dhparam /olsystem/etc/nginx/dhparam-2048.pem;

    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_ciphers EECDH+CHACHA20:EECDH+AES128:RSA+AES128:EECDH+AES256:RSA+AES256:EECDH+3DES:RSA+3DES:!MD5;
    ssl_prefer_server_ciphers on;

    # Needed for logging/IP anonymization
    include /olsystem/etc/nginx/logging_periodics.conf;
}

server {
    listen 80;
    listen 443;
    server_name  openlibrary.org;

    # Set the referrer policy so browsers send referrers to our own servers
    # In July 2020, Chrome changed its default referrer policy so any cross-origin
    # requests only sent the root referrer `/`. Since openlibrary.org
    # has a different "origin" than analytics.archive.org, the full referrer
    # path is not sent. This changes the behavior back to the pre-July 2020 change.
    add_header Referrer-Policy "no-referrer-when-downgrade";

    root        /openlibrary;

    # Show closed-library page on errors.
    error_page 502 /static/status-500.html;
    error_page 500 /static/status-500.html;

    # Anand - Oct 2013
    # Redirect all http URLs except the API calls (ending with .json or /api/*) to https
    set $api_call "$scheme:noapi";
    if ($uri ~ '\.json$') {
        set $api_call "$scheme:api";
    }
    if ($uri ~ '^/api/.*$') {
        set $api_call "$scheme:api";
    }
    if ($api_call = "http:noapi") {
        rewrite ^(.*)$ https://$http_host$1 last;
    }

    # Blue Sky
    location /.well-known/atproto-did {
        default_type text/plain;
        return 200 'did:plc:gtjpwquxcbc5sygj5vcfefb3';
    }

    # Return 429 errors as JSON.
    error_page 429 = @429;
# Needed for IP anonymization
load_module modules/ngx_http_js_module.so;

user  www-data;

# XXX-Anand: Oct 2013
# Increased the worker_processes to allow more workers to share the load of https.

#worker_processes  1;
worker_processes 4;


error_log  /var/log/nginx/error.log;
pid        /var/run/nginx.pid;

events {
    worker_connections  2048;
    # multi_accept on;
}

http {
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_session_cache   shared:SSL:50m;
    ssl_session_timeout 10m;

    include       /etc/nginx/mime.types;

    server_names_hash_bucket_size   64;
    types_hash_bucket_size 64;

    # Logging / IP Anonymization; also need logging_periodics.conf inside a server block
    include /olsystem/etc/nginx/logging.conf;
    access_log    /var/log/nginx/access.log iacombined;

    client_max_body_size 50m;

    sendfile        on;
    #tcp_nopush     on;

    #keepalive_timeout  0;
    keepalive_timeout  65;
    tcp_nodelay        on;

    gzip  on;
    gzip_disable "MSIE [1-6]\.(?!.*SV1)";
    gzip_types       text/plain text/css application/x-javascript application/javascript application/xml;

    # Black-listed IPs
    include /olsystem/etc/nginx/deny.conf;

    # Rate limiting: https://nginx.org/en/docs/http/ngx_http_limit_req_module.html
    # These rules only do anything if invoked, e.g., in web_nginx.conf.
    # TLDR: these rules can be disabled in `docker/web_nginx.conf`
    # and `docker/covers_nginx.conf`.
    geo $should_apply_limit {
      # No rate limit when IP obfuscation is not applied, as every IP is 255.0.0.0.
      255.0.0.0 0;
      # In cluster traffic
      207.241.224.0/20 0;
      # All other traffic
      default 1;
    }

    map $should_apply_limit $rate_limit_key {
      0 '';
      1 $binary_remote_addr;
    }

    # Matches other sites
    limit_req_zone $rate_limit_key zone=web_limit:10m rate=1r/s;
    # Higher rate for APIs since they are cheaper and we often hit them
    # multiple times per page load.
    limit_req_zone $rate_limit_key zone=api_limit:10m rate=180r/m;
    # Set a more permissive limit for covers because some pages might load 20+ covers.
    limit_req_zone $rate_limit_key zone=cover_limit:10m rate=400r/m;

    # Things are mounted into here by the docker compose file
    include /etc/nginx/sites-enabled/*;
}

